function generateSetupScript({ ssmParamName, provisioningKey, region }) {
  // Use a regular string with explicit \n to avoid bash ${ } clashing with JS template literals
  const inlineKey = provisioningKey || 'PASTE_YOUR_PROVISIONING_KEY_HERE'
  const ssmParam = ssmParamName || '/zpa/provisioning-key'

  const lines = [
    '#!/bin/bash',
    'set -euo pipefail',
    '',
    'echo "=============================================="',
    'echo " ZPA App Scanner Setup Script"',
    'echo " Generated by ZPA Shield Deployer"',
    'echo "=============================================="',
    '',
    '# === Step 1: Expand /var if needed ===',
    'echo "=== Step 1: Checking /var disk space ==="',
    'VAR_FREE_GB=$(df --output=avail -BG /var | tail -1 | tr -d \'G \')',
    'echo "Free space in /var: ${VAR_FREE_GB}GB"',
    '',
    'if [ "$VAR_FREE_GB" -lt 120 ]; then',
    '  echo "=== Step 1a: /var has less than 120GB free — expanding ==="',
    '  dnf install -y cloud-utils-growpart',
    '  VAR_LV=$(df /var | tail -1 | awk \'{print $1}\')',
    '  VAR_VG=$(lvs --noheadings -o vg_name "$VAR_LV" 2>/dev/null | tr -d \' \' || true)',
    '  if [ -n "$VAR_VG" ]; then',
    '    PV_DEVICE=$(pvs --noheadings -o pv_name,vg_name | grep "$VAR_VG" | awk \'{print $1}\')',
    '    DISK=$(lsblk -no PKNAME "$PV_DEVICE" | head -1)',
    '    PART_NUM=$(echo "$PV_DEVICE" | grep -o \'[0-9]*$\')',
    '    echo "Expanding: disk=/dev/$DISK part=$PART_NUM lv=$VAR_LV"',
    '    growpart /dev/$DISK $PART_NUM || true',
    '    pvresize "$PV_DEVICE" || true',
    '    lvextend -l +100%FREE "$VAR_LV" || true',
    '    xfs_growfs /var || resize2fs "$VAR_LV" || true',
    '  else',
    '    echo "WARNING: Could not detect LVM layout for /var — skipping. Please expand manually."',
    '  fi',
    '  echo "=== Step 1a: /var expansion complete ==="',
    'else',
    '  echo "=== Step 1: /var has sufficient space. Skipping expansion. ==="',
    'fi',
    '',
    '# === Step 2: Add Zscaler yum repository ===',
    'echo "=== Step 2: Adding Zscaler EL9 repository ==="',
    'cat > /etc/yum.repos.d/zscaler.repo << \'ZSCALER_REPO\'',
    '[zscaler]',
    'name=Zscaler Private Access Repository',
    'baseurl=https://yum.private.zscaler.com/yum/el9',
    'enabled=1',
    'gpgcheck=1',
    'gpgkey=https://yum.private.zscaler.com/yum/el9/gpg',
    'ZSCALER_REPO',
    '',
    '# === Step 3: Install App Connector ===',
    'echo "=== Step 3: Installing ZPA App Connector ==="',
    'dnf install -y zpa-connector',
    'systemctl stop zpa-connector || true',
    '',
    '# === Step 4: Write provisioning key ===',
    'echo "=== Step 4: Writing provisioning key ==="',
    'touch /opt/zscaler/var/provision_key',
    'chmod 644 /opt/zscaler/var/provision_key',
    '',
    '# Detect EC2 via instance metadata',
    'IS_EC2=false',
    'if curl -sf --max-time 2 http://169.254.169.254/latest/meta-data/instance-id > /dev/null 2>&1; then',
    '  IS_EC2=true',
    'fi',
    '',
    `if [ "$IS_EC2" = "true" ]; then`,
    `  echo "Fetching provisioning key from SSM: ${ssmParam}"`,
    '  TOKEN=$(curl -sf -X PUT "http://169.254.169.254/latest/api/token" -H "X-aws-ec2-metadata-token-ttl-seconds: 21600")',
    '  REGION=$(curl -sf -H "X-aws-ec2-metadata-token: $TOKEN" http://169.254.169.254/latest/meta-data/placement/region)',
    `  PROV_KEY=$(aws ssm get-parameter --name "${ssmParam}" --with-decryption --query "Parameter.Value" --output text --region "$REGION")`,
    '  echo "$PROV_KEY" > /opt/zscaler/var/provision_key',
    'else',
    '  # Inline provisioning key (CloudShare or non-EC2)',
    `  echo '${inlineKey}' > /opt/zscaler/var/provision_key`,
    'fi',
    '',
    'chmod 644 /opt/zscaler/var/provision_key',
    '',
    '# === Step 5: Install Docker ===',
    'echo "=== Step 5: Installing Docker ==="',
    'dnf install -y yum-utils',
    'yum-config-manager --add-repo https://download.docker.com/linux/centos/docker-ce.repo',
    'dnf install -y docker-ce docker-ce-cli containerd.io docker-buildx-plugin docker-compose-plugin',
    'systemctl start docker',
    'systemctl enable docker',
    '',
    '# === Step 6: Start App Connector ===',
    'echo "=== Step 6: Starting ZPA App Connector ==="',
    'systemctl start zpa-connector',
    'systemctl enable zpa-connector',
    '',
    'echo ""',
    'echo "=============================================="',
    'echo " Setup complete!"',
    'echo " Next steps in ZPA Admin Portal:"',
    'echo " 1. Assign AppShield 1.0 scanner version profile"',
    'echo " 2. Enable Application Shield Scanning on this connector"',
    'echo " 3. Verify connector shows healthy"',
    'echo "=============================================="',
    'echo "=== Rebooting in 10 seconds ==="',
    'sleep 10',
    'reboot',
  ]

  return lines.join('\n')
}

module.exports = { generateSetupScript }
